import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel for matrix multiplication (naive)
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Each thread computes one element of the output matrix C[i][j]
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    int n = a.size(0);  // assuming square matrices
    auto out = torch::zeros_like(a);
    const int block_size = 256;
    const int num_blocks_x = (n + block_size - 1) / block_size;
    const int num_blocks_y = (n + block_size - 1) / block_size;
    matmul_kernel<<<num_blocks_x, num_blocks_y>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), n);
    return out;
}
"""

matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b);"

# Kernel for upper triangular extraction (zero lower part)
triu_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void triu_kernel(const float* out, const float* in, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n * n) {
        int row = idx / n;
        int col = idx % n;
        if (row <= col) {
            out[idx] = in[idx];
        } else {
            out[idx] = 0.0f;
        }
    }
}

torch::Tensor triu_cuda(torch::Tensor a, int n) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    triu_kernel<<<num_blocks, block_size>>>(out.data_ptr<float>(), a.data_ptr<float>(), n);
    return out;
}
"""

triu_cpp_source = "torch::Tensor triu_cuda(torch::Tensor a, int n);"

# Compile matmul
matmul = load_inline(
    name="matmul_cuda",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_kernel_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# Compile triu
triu = load_inline(
    name="triu_cuda",
    cpp_sources=triu_cpp_source,
    cuda_sources=triu_kernel_source,
    functions=["triu_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_cuda = matmul
        self.triu_cuda = triu

    def forward(self, A, B):
        C = self.matmul_cuda(A, B)
        n = A.size(0)
        return self.triu_cuda(C, n)
